from datetime import date, timedelta

# Find the earliest Friday the 13th starting from 0001-01-01 (proleptic Gregorian)
d = date(1, 1, 13)  # start checking the 13th of each month
earliest = None
while d.year == 1:
    if d.weekday() == 4:  # Friday
        earliest = d
        break
    # advance to 13th of next month
    if d.month == 12:
        break
    d = d.replace(month=d.month + 1)

if not earliest:
    # check year 2 onward
    for y in range(2, 401):
        for m in range(1, 13):
            d = date(y, m, 13)
            if d.weekday() == 4:
                earliest = d
                break
        if earliest:
            break

# Actually let's just scan from year 1
earliest = None
for y in range(1, 401):
    for m in range(1, 13):
        d = date(y, m, 13)
        if d.weekday() == 4:
            if earliest is None:
                earliest = d
            break
    if earliest:
        break

print(f"Earliest Friday the 13th: {earliest} ({earliest.strftime('%A, %B %d, %Y')})")

# Count Friday the 13ths in a full 400-year cycle (years 1-400)
# The Gregorian calendar repeats every 400 years exactly
count = 0
for y in range(1, 401):
    for m in range(1, 13):
        if date(y, m, 13).weekday() == 4:
            count += 1

print(f"\nFriday the 13ths in a 400-year cycle: {count}")
print(f"Average per year: {count/400:.4f}")
print(f"Average per month: {count/(400*12):.6f}")

# Bonus: distribution by month
from collections import Counter
by_month = Counter()
for y in range(1, 401):
    for m in range(1, 13):
        if date(y, m, 13).weekday() == 4:
            by_month[m] += 1

print("\nDistribution by month:")
import calendar
for m in range(1, 13):
    print(f"  {calendar.month_abbr[m]:>3}: {by_month[m]}")
EOF

